-- Seed: Indicadores de 2do de Secundaria - Lenguas Extranjeras (Inglés)

INSERT INTO public.curr_indicadores (grado, asignatura, competencia, codigo, descripcion) VALUES
-- BC1
('2do', 'Lenguas Extranjeras (Inglés)', 'BC1', 'IL-1', 'Responde de forma adecuada a preguntas e indicaciones, a partir de la escucha o lectura de textos breves y sencillos que contienen información sobre su entorno inmediato, actividades cotidianas, estados de salud, sentimientos, intereses, consejos, planes sugerencias, y narraciones de experiencias.'),
('2do', 'Lenguas Extranjeras (Inglés)', 'BC1', 'IL-2', 'Produce textos breves y sencillos mediante una serie de frases y oraciones enlazadas por conectores básicos para compartir informaciones personales y de su entorno inmediato, tales como experiencias, estados de salud, sentimientos, planes, consejos y sugerencias, con pausas y reformulaciones en lo oral y con algunos errores básicos en lo escrito.'),
('2do', 'Lenguas Extranjeras (Inglés)', 'BC1', 'IL-3', 'Interactúa en forma oral o escrita a través de una serie de frases y oraciones sencillas, enlazadas por conectores, con el propósito de informar sobre actividades cotidianas, describir estados anímicos y físicos, solicitar ayuda, comprar, expresar deseo o interés, dar consejos y sugerencias, expresar planes y narrar experiencias, aunque con algunos errores básicos.'),

-- BC2
('2do', 'Lenguas Extranjeras (Inglés)', 'BC2', 'IL-4', 'Responde de forma adecuada a preguntas e indicaciones, a partir de textos orales y escritos breves y sencillos donde se presenta información variada y sugerencias sobre situaciones presentes, futuras y pasadas, comprendiendo de forma reflexiva y creativa la secuencia y relación lógica de los elementos.'),
('2do', 'Lenguas Extranjeras (Inglés)', 'BC2', 'IL-5', 'Produce textos orales y escritos breves y sencillos con claridad y creatividad, manteniendo una secuencia clara y ordenada de las ideas, mediante el uso de conectores lógicos básicos apropiados a la relación específica de las ideas, al tema y la situación.'),
('2do', 'Lenguas Extranjeras (Inglés)', 'BC2', 'IL-6', 'Interactúa en forma oral o escrita a través de una serie de oraciones breves y sencillas ordenadas de una forma lógica y presentadas de forma creativa en diferentes tipos de texto donde comparte experiencias, información, planes, sugerencias, y consejos.'),
('2do', 'Lenguas Extranjeras (Inglés)', 'BC2', 'IL-7', 'Responde de forma adecuada a preguntas e indicaciones sobre situaciones y problemas de su entorno inmediato y temas que le son familiares, a partir de textos orales y escritos breves y sencillos.'),
('2do', 'Lenguas Extranjeras (Inglés)', 'BC2', 'IL-8', 'Se comunica mediante textos orales y escritos de forma clara y comprensible, para comunicar problemas inmediatos propios, de otras personas y del entorno cotidiano, así como para proponer consejos y sugerencias pertinentes, utilizando frases y oraciones breves y sencillas.'),
('2do', 'Lenguas Extranjeras (Inglés)', 'BC2', 'IL-9', 'Interactúa de forma oral y escrita para solicitar o proveer información, ayuda, consejos y sugerencias sobre situaciones y problemas relativos a actividades cotidianas, intereses y estados de ánimo, utilizando con claridad frases y oraciones breves y sencillas.'),

-- BC3
('2do', 'Lenguas Extranjeras (Inglés)', 'BC3', 'IL-13', 'Identifica información y la utiliza de forma adecuada para responder a preguntas e indicaciones sobre aspectos científicos y tecnológicos presentes en la descripción de actividades cotidianas, experiencias, sentimientos y dolencias propias y de otras personas.'),
('2do', 'Lenguas Extranjeras (Inglés)', 'BC3', 'IL-14', 'Expresa ideas y sugerencias sobre aspectos de temas científicos, tecnológicos y de otra índole presentes en su entorno inmediato de interés personal para referirse a la salud, estados de ánimo, deseos y experiencias pasadas, utilizando oraciones comunes breves y sencillas.'),
('2do', 'Lengua Extranjeras (Inglés)', 'BC3', 'IL-15', 'Interactúa sobre temas científicos, tecnológicos y de otra índole con el propósito de pedir y dar consejos y sugerencias, de forma presencial o virtual, utilizando vocabulario común con frases y oraciones breves y sencillas.'),
('2do', 'Lenguas Extranjeras (Inglés)', 'BC3', 'IL-16', 'Identifica las acciones que impactan positivamente la salud y el medio ambiente en las actividades cotidianas que se realizan en su entorno inmediato.'),
('2do', 'Lenguas Extranjeras (Inglés)', 'BC3', 'IL-17', 'Describe información del estado de su entorno inmediato, presentando consejos, sugerencias y planes para cuidar el medioambiente, la salud propia y de otras personas.'),
('2do', 'Lenguas Extranjeras (Inglés)', 'BC3', 'IL-18', 'Interactúa de forma adecuada en situaciones donde se promueve prácticas de hábitos saludables para las personas y amigables con el medioambiente.'),

-- BC4
('2do', 'Lenguas Extranjeras (Inglés)', 'BC4', 'IL-10', 'Reconoce las diferencias individuales y la identidad social y cultural propia y de otros países como gestos, compras, celebraciones, actividades de tiempo libre, puntualidad y lugares de interés.'),
('2do', 'Lenguas Extranjeras (Inglés)', 'BC4', 'IL-11', 'Interactúa de forma breve y sencilla en el idioma inglés, con cortesía, asertividad y respeto.'),
('2do', 'Lenguas Extranjeras (Inglés)', 'BC4', 'IL-12', 'Sostiene la conversación al interactuar en forma oral o escrita, utilizando frases y oraciones estratégicas para mantener la interacción de forma cortés y respetuosa a las diferencias de la cultura personal y de otras personas.'),
('2do', 'Lenguas Extranjeras (Inglés)', 'BC4', 'IL-19', 'Muestra empatía por los sentimientos y necesidades de las demás personas.'),
('2do', 'Lenguas Extranjeras (Inglés)', 'BC4', 'IL-20', 'Muestra disposición para ayudar a las demás personas que lo necesitan, al interactuar con sus compañeros de forma colaborativa.'),
('2do', 'Lenguas Extranjeras (Inglés)', 'BC4', 'IL-21', 'Interactúa con cortesía, respeto y asertividad al referirse a sí mismo y a otras personas.');
